frappe.listview_settings["Purchase Invoice"] = {
    add_fields: ["supplier", "custom_expense_account_display"],
    onload: function(listview) {
        setTimeout(() => {
            // Fix checkbox alignment
            let style = document.createElement("style");
            style.innerHTML = `
                .list-row .level-left .list-row-col:first-child,
                .list-row-head .level-left .list-row-col:first-child {
                    width: 32px !important;
                    min-width: 32px !important;
                    padding: 0 !important;
                    display: flex !important;
                    align-items: center !important;
                    justify-content: center !important;
                }
            `;
            document.head.appendChild(style);

            // Ganti Title → Supplier di header
            let titleHeader = document.querySelector("span[data-sort-by='title']");
            if (titleHeader) titleHeader.innerText = "Supplier";

            // Tambah header Expense Account
            let headRow = document.querySelector(".list-row-head .level-left");
            if (headRow && !headRow.querySelector(".expense-header")) {
                let newHeader = document.createElement("div");
                newHeader.className = "list-row-col ellipsis hidden-xs expense-header";
                newHeader.innerHTML = `<span>Expense Account</span>`;
                headRow.appendChild(newHeader);
            }

            // Process setiap row
            listview.data.forEach((doc, idx) => {
                let rows = document.querySelectorAll(".list-row");
                if (!rows[idx]) return;
                let parent = rows[idx].querySelector(".level-left");
                if (!parent) return;

                // Ganti supplier di subject
                let titleEl = parent.querySelector(".level-item.bold");
                if (titleEl) titleEl.innerText = doc.supplier || "-";

                // Tambah expense col jika belum ada
                if (!parent.querySelector(".expense-col")) {
                    let newCol = document.createElement("div");
                    newCol.className = "list-row-col ellipsis hidden-xs expense-col";
                    newCol.innerHTML = `<span>${doc.custom_expense_account_display || "-"}</span>`;
                    parent.appendChild(newCol);
                }

                let allCols = Array.from(parent.querySelectorAll(".list-row-col"));
                let subjectCol = allCols.find(c => c.classList.contains("list-subject"));
                let statusCol = allCols.find(c => c.querySelector(".indicator-pill"));
                let dateCol = allCols.find(c => c.querySelector(`a[data-filter*='posting_date']`));
                let idCol = allCols.find(c => c.querySelector(`a[data-filter*='name,=']`));
                let expenseCol = parent.querySelector(".expense-col");
                let grandTotalCol = allCols.find(c => 
                    c !== subjectCol && c !== statusCol && 
                    c !== dateCol && c !== idCol && 
                    c !== expenseCol && !c.classList.contains("tag-col"));

                // Pindah checkbox ke luar subjectCol
                let checkboxSpan = subjectCol ? subjectCol.querySelector(".select-like") : null;
                if (checkboxSpan && subjectCol) {
                    subjectCol.removeChild(checkboxSpan);
                }

                // Buat wrapper checkbox
                let checkboxCol = document.createElement("div");
                checkboxCol.className = "list-row-col ellipsis";
                checkboxCol.style.cssText = "width:32px; min-width:32px; padding:0 8px;";
                if (checkboxSpan) checkboxCol.appendChild(checkboxSpan);

                parent.innerHTML = "";
                parent.appendChild(checkboxCol);
                if (idCol) parent.appendChild(idCol);
                if (dateCol) parent.appendChild(dateCol);
                if (subjectCol) parent.appendChild(subjectCol);
                if (expenseCol) parent.appendChild(expenseCol);
                if (grandTotalCol) parent.appendChild(grandTotalCol);
                if (statusCol) parent.appendChild(statusCol);
            });

            // Reorder header
            let parent = document.querySelector(".list-row-head .level-left");
            if (parent) {
                let cols = Array.from(parent.querySelectorAll(".list-row-col"));
                let subjectCol = cols.find(c => c.classList.contains("list-subject"));
                let idCol = cols.find(c => c.querySelector("span[data-sort-by='name']"));
                let dateCol = cols.find(c => c.querySelector("span[data-sort-by='posting_date']"));
                let expenseCol = cols.find(c => c.classList.contains("expense-header"));
                let grandTotalCol = cols.find(c => c.innerText.trim() === "Grand Total");
                let statusCol = cols.find(c => c.innerText.trim() === "Status");

                // Pindah checkbox header
                let checkAll = subjectCol ? subjectCol.querySelector(".list-check-all") : null;
                if (checkAll && subjectCol) subjectCol.removeChild(checkAll);

                let checkboxHeaderCol = document.createElement("div");
                checkboxHeaderCol.className = "list-row-col ellipsis";
                checkboxHeaderCol.style.cssText = "width:32px; min-width:32px; padding:0 8px;";
                if (checkAll) checkboxHeaderCol.appendChild(checkAll);

                parent.innerHTML = "";
                parent.appendChild(checkboxHeaderCol);
                if (idCol) parent.appendChild(idCol);
                if (dateCol) parent.appendChild(dateCol);
                if (subjectCol) parent.appendChild(subjectCol);
                if (expenseCol) parent.appendChild(expenseCol);
                if (grandTotalCol) parent.appendChild(grandTotalCol);
                if (statusCol) parent.appendChild(statusCol);
            }

        }, 1000);
    }
};

frappe.ui.form.on('Purchase Invoice', {
  refresh(frm) {
    // Helper: determine source doctype from request name
    function _erDoctype(name) {
      return name && name.startsWith('ERMC-') ? 'Advanced Expense Request' : 'Expense Request';
    }

    // Set filter for Expense Request dropdown
    if (frm.fields_dict.imogi_expense_request) {
      frm.set_query('imogi_expense_request', () => ({
        filters: {
          docstatus: 1,
          status: ['in', ['Approved', 'PI Created']],
        },
      }));
    }

    // Fix: Force show tax fields (tax_category, taxes_and_charges)
    // These fields are hidden by Frappe's guardian_has_value logic
    // but are CRITICAL for PPN/PPh calculation from Expense Request
    setTimeout(() => {
      const taxFields = ['tax_category', 'taxes_and_charges'];
      const taxesSection = frm.fields_dict.taxes_section;

      // Force show tax fields
      taxFields.forEach(fieldname => {
        const field = frm.fields_dict[fieldname];
        if (field && field.wrapper) {
          $(field.wrapper).removeClass('hide-control');
          $(field.wrapper).show();
        }
      });

      // Force show taxes section
      if (taxesSection && taxesSection.wrapper) {
        $(taxesSection.wrapper).removeClass('empty-section');
        $(taxesSection.wrapper).show();
      }
    }, 100);

    // Show warning if PI is created manually (not from ER)

    // Show info if from ER
    if (frm.doc.imogi_expense_request && !frm.doc.__islocal) {
      frm.dashboard.set_headline_alert(
        'Purchase Invoice dibuat dari ' + _erDoctype(frm.doc.imogi_expense_request) + ': ' + frm.doc.imogi_expense_request,
        'blue'
      );
    }

    // Add "Create Payment Entry" button if PI is from ER and submitted
    if (frm.doc.imogi_expense_request && frm.doc.docstatus === 1 && !frm.doc.__islocal) {
      frm.add_custom_button(__('Create Payment Entry'), async () => {
        frappe.confirm(
          __('Create Payment Entry for this Purchase Invoice from') + ' ' + _erDoctype(frm.doc.imogi_expense_request) + ' ' + frm.doc.imogi_expense_request + '?',
          async () => {
            try {
              // Get ER data first
              const er_data = await frappe.db.get_doc(_erDoctype(frm.doc.imogi_expense_request), frm.doc.imogi_expense_request);

              // Create Payment Entry using get_payment_entry
              frappe.call({
                method: 'erpnext.accounts.doctype.payment_entry.payment_entry.get_payment_entry',
                args: {
                  dt: frm.doc.doctype,
                  dn: frm.doc.name
                },
                callback: function(r) {
                  if (r.message) {
                    const pe = frappe.model.sync(r.message);
                    frappe.set_route('Form', pe[0].doctype, pe[0].name);

                    // Set ER link and auto-fill remarks after navigation
                    setTimeout(() => {
                      const pe_frm = cur_frm;
                      if (pe_frm && pe_frm.doc.doctype === 'Payment Entry') {
                        pe_frm.set_value('imogi_expense_request', frm.doc.imogi_expense_request);
                        const remarks = 'Payment for ' + _erDoctype(er_data.name) + ' ' + er_data.name + ' - ' + (er_data.request_type || '');
                        pe_frm.set_value('remarks', remarks);
                      }
                    }, 500);
                  }
                },
                error: function(r) {
                  frappe.msgprint({
                    title: __('Error'),
                    message: r?.message || __('Failed to create Payment Entry'),
                    indicator: 'red',
                  });
                }
              });
            } catch (error) {
              frappe.msgprint({
                title: __('Error'),
                message: error?.message || __('Failed to create Payment Entry'),
                indicator: 'red',
              });
            }
          }
        );
      }, __('Actions'));
    }
  },
});

frappe.ui.form.on('Payment Entry', {
  refresh(frm) {
    // Helper: determine source doctype from request name
    function _erDoctype(name) {
      return name && name.startsWith('ERMC-') ? 'Advanced Expense Request' : 'Expense Request';
    }

    if (frm.fields_dict.imogi_expense_request) {
      frm.set_query('imogi_expense_request', () => ({
        filters: {
          docstatus: 1,
          status: ['in', ['PI Created']],
        },
      }));
    }

    // Validation: If PE is for PI linked to ER, must be created from PI button
    if (frm.doc.__islocal && frm.doc.payment_type === 'Pay') {
      // Check if references include PI with ER link
      const references = frm.doc.references || [];
      references.forEach(ref => {
        if (ref.reference_doctype === 'Purchase Invoice' && ref.reference_name) {
          frappe.db.get_value('Purchase Invoice', ref.reference_name, 'imogi_expense_request')
            .then(r => {
              if (r.message && r.message.imogi_expense_request) {
                frm.dashboard.set_headline_alert(
                  '<b>Perhatian:</b> Purchase Invoice ini terkait dengan Expense Request. Sebaiknya buat Payment Entry dari button "Create Payment Entry" di Purchase Invoice untuk flow yang benar.',
                  'orange'
                );
              }
            });
        }
      });
    }
  },
  imogi_expense_request(frm) {
    if (!frm.doc.imogi_expense_request) {
      return;
    }
    frappe.call({
      method: 'frappe.client.get',
      args: {
        doctype: _erDoctype(frm.doc.imogi_expense_request),
        name: frm.doc.imogi_expense_request,
      },
      callback(r) {
        if (r.message) {
          const er = r.message;
          if (er.total_amount) {
            frm.set_value('paid_amount', er.total_amount);
            frm.set_value('received_amount', er.total_amount);
          }
          if (!frm.doc.remarks || !frm.doc.remarks.includes('Expense Request')) {
            const remarks = 'Payment for ' + (er.doctype || _erDoctype(er.name)) + ' ' + er.name + ' - ' + (er.request_type || '');
            frm.set_value('remarks', remarks);
          }
        }
      },
    });
  },
});

