    // Re-apply filter whenever account_type changes
    refresh_field('account', cdn, 'gl_account_mappings');
  },
  account_parent(frm, cdt, cdn) {
    // Clear account if parent changes
    const row = locals[cdt][cdn];
    if (row.account) {
      frappe.model.set_value(cdt, cdn, 'account', '');
    }
    refresh_field('account', cdn, 'gl_account_mappings');
  },
});

frappe.ui.form.on('Finance Control Settings', {
  refresh(frm) {
    // Apply dynamic filter on 'account' field in gl_account_mappings
    frm.set_query('account', 'gl_account_mappings', function(doc, cdt, cdn) {
      const row = locals[cdt][cdn];
      const filters = { is_group: 0 };
      if (row.account_type) {
        filters['account_type'] = row.account_type;
      }
      if (row.account_parent) {
        filters['parent_account'] = row.account_parent;
      }
      if (doc.company) {
        filters['company'] = doc.company;
      } else if (row.company) {
        filters['company'] = row.company;
      }
      return { filters };
    });

    // Apply dynamic filter on 'account_parent' field in gl_account_mappings
    frm.set_query('account_parent', 'gl_account_mappings', function(doc, cdt, cdn) {
      const row = locals[cdt][cdn];
      const filters = { is_group: 1 };
      if (row.account_type) {
        filters['account_type'] = row.account_type;
      }
      if (doc.company) {
        filters['company'] = doc.company;
      } else if (row.company) {
        filters['company'] = row.company;
      }
      return { filters };
    });
  },
});

