            border:1px solid #dde5ee;
            border-radius:999px;
            padding:3px 8px;
          }

          .erg-lvl-1{ margin-top:10px; }
          .erg-lvl-2{ margin-left:18px; background:#fbfcfd; }
          .erg-lvl-3{ margin-left:36px; background:#fcfdfe; }
          .erg-lvl-4{ margin-left:54px; background:#ffffff; }
          .erg-lvl-5{ margin-left:72px; background:#ffffff; }

          .erg-hidden-by-collapse{
            display:none !important;
          }
        </style>
      `);
    }

    function monthNames() {
      return [
        "Januari", "Februari", "Maret", "April", "Mei", "Juni",
        "Juli", "Agustus", "September", "Oktober", "November", "Desember"
      ];
    }

    function parseDate(date_str) {
      if (!date_str) return null;
      return frappe.datetime.str_to_obj(date_str);
    }

    function getQuarter(monthIndex) {
      return Math.floor(monthIndex / 3) + 1;
    }

    function getWeekOfMonth(dt) {
      const firstDay = new Date(dt.getFullYear(), dt.getMonth(), 1);
      return Math.ceil((dt.getDate() + firstDay.getDay()) / 7);
    }

    function getGroupValue(dateObj, mode) {
      if (!dateObj) {
        return { key: "NO_DATE", label: "No Date", year: "NO_DATE" };
      }

      const y = dateObj.getFullYear();
      const m = dateObj.getMonth();
      const d = dateObj.getDate();
      const months = monthNames();

      if (mode === "Year") {
        return { key: String(y), label: String(y), year: String(y) };
      }
      if (mode === "Quarter") {
        const q = getQuarter(m);
        return { key: `${y}-Q${q}`, label: `Q${q} ${y}`, year: String(y) };
      }
      if (mode === "Month") {
        return {
          key: `${y}-${String(m + 1).padStart(2, "0")}`,
          label: `${months[m]} ${y}`,
          year: String(y)
        };
      }
      if (mode === "Week") {
        const w = getWeekOfMonth(dateObj);
        return {
          key: `${y}-${String(m + 1).padStart(2, "0")}-W${w}`,
          label: `Minggu ${w} - ${months[m]} ${y}`,
          year: String(y)
        };
      }
      if (mode === "Day") {
        return {
          key: `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`,
          label: `${String(d).padStart(2, "0")} ${months[m]} ${y}`,
          year: String(y)
        };
      }

      return { key: "UNKNOWN", label: "Unknown", year: "UNKNOWN" };
    }

    function escapeHtml(text) {
      return frappe.utils.escape_html(text == null ? "" : String(text));
    }

    function removeGroupingArtifacts() {
      if (!listview.$result) return;
      listview.$result.find(".erg-group-header").remove();
      listview.$result.find(".erg-group-separator").remove();
      listview.$result.find(".erg-hidden-by-collapse").removeClass("erg-hidden-by-collapse");
    }

    function getRowElements() {
      if (!listview.$result) return $();
      return listview.$result.find(".list-row-container").filter(function () {
        return !!getDocNameFromRow($(this));
      });
    }

    function getDocNameFromRow($row) {
      return (
        $row.attr("data-name") ||
        $row.find("[data-name]").first().attr("data-name") ||
        $row.find(".list-subject a").first().attr("data-name") ||
        null
      );
    }

    function getDocByName(name) {
      if (!Array.isArray(listview.data)) return null;
      return listview.data.find(d => d.name === name) || null;
    }

    function buildGroupChain(dateVal) {
      const d = parseDate(dateVal);
      return selected_groups.map(function (mode) {
        const item = getGroupValue(d, mode);
        return {
          mode,
          key: String(item.key).trim(),
          label: item.label,
          year: item.year
        };
      });
    }

    function makeSeparator() {
      return $('<div class="erg-group-separator"></div>');
    }

    function makeGroupHeader(level, mode, label, subtext, chainKey) {
      const safeLabel = escapeHtml(label);
      const safeSub   = escapeHtml(subtext || "");
      const safeMode  = escapeHtml(mode);
      const safeKey   = escapeHtml(chainKey);
      const isCollapsed = !!collapsed_groups[chainKey];

      return $(`
        <div class="erg-group-header erg-lvl-${level}"
             data-group-level="${level}"
             data-chain-key="${safeKey}"
             data-collapsed="${isCollapsed ? "1" : "0"}">
          <div class="erg-group-left">
            <div class="erg-group-toggle">${isCollapsed ? "▸" : "▾"}</div>
            <div class="erg-group-text">
              <div class="erg-group-title">${safeLabel}</div>
              <div class="erg-group-sub">${safeSub}</div>
            </div>
          </div>
          <div class="erg-group-badge">${safeMode}</div>
        </div>
      `);
    }

    function getSubText(level, mode, groupItem, fullChain) {
      if (mode === "Year") return "Group by Tahun";
      if (level === 1) return "Level utama";
      return fullChain.slice(0, level - 1).map(x => x.label).join(" / ");
    }

    function collapseFromHeader($header) {
      const currentLevel = parseInt($header.attr("data-group-level"), 10);
      const chainKey = $header.attr("data-chain-key");
      let $next = $header.next();

      collapsed_groups[chainKey] = true;
      $header.attr("data-collapsed", "1");
      $header.find(".erg-group-toggle").text("▸");

      while ($next.length) {
        if ($next.hasClass("erg-group-header")) {
          const nextLevel = parseInt($next.attr("data-group-level"), 10);
          if (nextLevel <= currentLevel) break;
        }
        $next.addClass("erg-hidden-by-collapse");
        $next = $next.next();
      }
    }

    function expandFromHeader($header) {
      const currentLevel = parseInt($header.attr("data-group-level"), 10);
      const chainKey = $header.attr("data-chain-key");
      let $next = $header.next();

      delete collapsed_groups[chainKey];
      $header.attr("data-collapsed", "0");
      $header.find(".erg-group-toggle").text("▾");

      while ($next.length) {
        if ($next.hasClass("erg-group-header")) {
          const nextLevel = parseInt($next.attr("data-group-level"), 10);
          if (nextLevel <= currentLevel) break;

          $next.removeClass("erg-hidden-by-collapse");

          if ($next.attr("data-collapsed") === "1") {
            let $skip = $next.next();
            while ($skip.length) {
              if ($skip.hasClass("erg-group-header")) {
                const skipLevel = parseInt($skip.attr("data-group-level"), 10);
                if (skipLevel <= nextLevel) break;
              }
              $skip.addClass("erg-hidden-by-collapse");
              $skip = $skip.next();
            }
          }
        } else {
          $next.removeClass("erg-hidden-by-collapse");
        }
        $next = $next.next();
      }

      reapplyCollapsedParents();
    }

    function reapplyCollapsedParents() {
      listview.$result.find(".erg-group-header[data-collapsed='1']").each(function () {
        collapseFromHeader($(this));
      });
    }

    function bindCollapseEvents() {
      listview.$result.find(".erg-group-header")
        .off("click.ergcollapse")
        .on("click.ergcollapse", function (e) {
          e.stopPropagation();
          const $header = $(this);
          const isCollapsed = $header.attr("data-collapsed") === "1";
          if (isCollapsed) expandFromHeader($header);
          else collapseFromHeader($header);
        });
    }

    function collapseAllHeaders() {
      listview.$result.find(".erg-group-header").each(function () {
        collapseFromHeader($(this));
      });
    }

    function getSortedRowMeta() {
      const rows = [];

      getRowElements().each(function () {
        const $row    = $(this);
        const docname = getDocNameFromRow($row);
        if (!docname) return;

        const rowDoc  = getDocByName(docname);
        const dateVal = rowDoc ? rowDoc[DATE_FIELD] : null;
        const dateObj = parseDate(dateVal);

        rows.push({
          $row, docname, doc: rowDoc, dateVal, dateObj,
          ts: dateObj ? dateObj.getTime() : 0
        });
      });

      rows.sort(function (a, b) {
        if (a.ts !== b.ts) return a.ts - b.ts;
        return String(a.docname).localeCompare(String(b.docname));
      });

      return rows;
    }

    function reorderRowsByDate(sortedRows) {
      if (!sortedRows.length || !listview.$result) return;
      const $parent = sortedRows[0].$row.parent();
      if (!$parent.length) return;
      sortedRows.forEach(function (item) { $parent.append(item.$row); });
    }

    function applyGrouping() {
      if (is_rendering_groups) return;
      if (!listview.$result) return;

      is_rendering_groups = true;

      try {
        removeGroupingArtifacts();
        if (!selected_groups.length) return;

        const sortedRows = getSortedRowMeta();
        if (!sortedRows.length) return;

        reorderRowsByDate(sortedRows);

        let prevChainKeys = [];
        let prevTopKey = null;

        sortedRows.forEach(function (item) {
          const $row  = item.$row;
          const chain = buildGroupChain(item.dateVal);
          if (!chain.length) return;

          const topKey = `${chain[0].mode}:${chain[0].key}`;

          chain.forEach(function (groupItem, idx) {
            const level      = idx + 1;
            const partialKey = chain.slice(0, level).map(x => `${x.mode}:${x.key}`).join("||");

            if (prevChainKeys[idx] !== partialKey) {
              if (idx === 0 && prevTopKey !== null && topKey !== prevTopKey) {
                $row.before(makeSeparator());
              }
              const subtext = getSubText(level, groupItem.mode, groupItem, chain);
              $row.before(makeGroupHeader(level, groupItem.mode, groupItem.label, subtext, partialKey));

              prevChainKeys[idx] = partialKey;
              for (let j = idx + 1; j < prevChainKeys.length; j++) prevChainKeys[j] = null;
            }
          });

          prevTopKey = topKey;
        });

        bindCollapseEvents();
        reapplyCollapsedParents();

        if (Object.keys(collapsed_groups).length === 0) {
          collapseAllHeaders();
        }
      } finally {
        is_rendering_groups = false;
      }
    }

    function scheduleApplyGrouping(delay = 400) {
      clearTimeout(apply_timer);
      apply_timer = setTimeout(function () { applyGrouping(); }, delay);
    }

    function updateGroupDisplay() {
      if (selected_groups.length) {
        $("#erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder");
        $("#erg-clr").show();
      } else {
        $("#erg-text").text("Group By").addClass("is-placeholder");
        $("#erg-clr").hide();
      }
    }

    function buildGroupingWrap() {
      const optionsHtml = GROUP_OPTIONS.map(function (opt) {
        return `
          <label class="erg-opt">
            <input type="checkbox" class="erg-opt-check" value="${opt}">
            <span>${opt}</span>
          </label>
        `;
      }).join("");

      return $(`
        <div id="erg-wrap">
          <div id="erg-select">
            <span id="erg-text" class="is-placeholder">Group By</span>
          </div>
          <div id="erg-chevron">
            <svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg>
          </div>
          <span id="erg-clr">×</span>
          <div id="erg-dd">
            <div class="erg-dd-title">Pilih lebih dari 1 grouping level</div>
            ${optionsHtml}
            <div class="erg-dd-actions">
              <button type="button" class="erg-dd-btn" id="erg-select-all">All</button>
              <button type="button" class="erg-dd-btn" id="erg-clear-all">Clear</button>
              <button type="button" class="erg-dd-btn" id="erg-apply">Apply</button>
            </div>
          </div>
        </div>
      `);
    }

    function syncDropdownChecks() {
      $("#erg-dd .erg-opt-check").each(function () {
        $(this).prop("checked", selected_groups.includes($(this).val()));
      });
    }

    function attachGroupingEvents($wrap) {
      $wrap.on("click", "#erg-select", function (e) {
        e.stopPropagation();
        syncDropdownChecks();
        $("#erg-dd").toggle();
      });

      $wrap.on("click", "#erg-select-all", function (e) {
        e.stopPropagation();
        $("#erg-dd .erg-opt-check").prop("checked", true);
      });

      $wrap.on("click", "#erg-clear-all", function (e) {
        e.stopPropagation();
        $("#erg-dd .erg-opt-check").prop("checked", false);
      });

      $wrap.on("click", "#erg-apply", function (e) {
        e.stopPropagation();
        selected_groups = [];
        $("#erg-dd .erg-opt-check:checked").each(function () {
          selected_groups.push($(this).val());
        });
        selected_groups = GROUP_OPTIONS.filter(opt => selected_groups.includes(opt));
        collapsed_groups = {};
        updateGroupDisplay();
        $("#erg-dd").hide();
        scheduleApplyGrouping(300);
      });

      $wrap.on("click", "#erg-clr", function (e) {
        e.stopPropagation();
        selected_groups = [];
        collapsed_groups = {};
        updateGroupDisplay();
        removeGroupingArtifacts();
        syncDropdownChecks();
      });

      $(document).off("click.erg").on("click.erg", function () { $("#erg-dd").hide(); });
      $wrap.on("click", "#erg-dd", function (e) { e.stopPropagation(); });
    }

    function injectGroupingUI() {
      $("#erg-wrap").remove();

      const $alloc = $('[data-fieldname="allocation_mode"].frappe-control');
      if (!$alloc.length) return false;

      const $wrap = buildGroupingWrap();
      $alloc.after($wrap);
      attachGroupingEvents($wrap);
      updateGroupDisplay();
      syncDropdownChecks();
      return true;
    }

    if (!listview.__erg_grouping_patched_render) {
      listview.__erg_grouping_patched_render = true;
      const originalRender = listview.render;
      listview.render = function () {
        const out = originalRender.apply(this, arguments);
        scheduleApplyGrouping(500);
        return out;
      };
    }

    if (!listview.__erg_grouping_patched_refresh) {
      listview.__erg_grouping_patched_refresh = true;
      const originalRefresh = listview.refresh;
      listview.refresh = function () {
        const out = originalRefresh.apply(this, arguments);
        scheduleApplyGrouping(600);
        return out;
      };
    }

    frappe.after_ajax(function () {
      if (!injectGroupingUI()) {
        let n = 0;
        const iv = setInterval(function () {
          n++;
          if (injectGroupingUI() || n > 20) clearInterval(iv);
        }, 200);
      }
      scheduleApplyGrouping(700);
    });
  }
};
